const slug = $json.slug || 'sample-worktree';
const worktreePath = $json.worktreePath || '/abs/path/to/worktrees/sample';
const branch = $json.branch || '';
const escaped = (value) => `'${String(value).replace(/'/g, `'"'"'`)}'`;
const branchArg = branch ? ` --branch ${escaped(branch)}` : '';
return [{ command: `cd /home/gandalfalex/projects/coding-agent-workflow && infra/worktree-deployer/scripts/create-worktree-deploy.sh --slug ${escaped(slug)} --worktree-path ${escaped(worktreePath)}${branchArg}` }];
